import type { Catalog } from '../types.ts'
import { admissions } from './admissions.ts'
import { careers } from './careers.ts'
import { categories } from './categories.ts'
import { courses } from './courses.ts'
import { institutions, programmes, sources } from './institutions.ts'
import { pathways } from './pathways.ts'
import { quizOptions, quizQuestions } from './quiz.ts'

/**
 * Builds a fresh copy of the bundled sample catalog.
 * This is the single source of truth for both demo mode and supabase/seed.sql
 * (generated by `npm run seed:sql`).
 */
export function buildSeedCatalog(): Catalog {
  return structuredClone({
    categories,
    pathways,
    courses: courses.map(({ pathways: _p, careers: _c, ...c }) => ({ ...c, published: true })),
    careers: careers.map((c) => ({ ...c, published: true })),
    coursePathways: courses.flatMap((c) => c.pathways.map((pathway_id) => ({ course_id: c.id, pathway_id }))),
    courseCareers: courses.flatMap((c) => c.careers.map((career_id) => ({ course_id: c.id, career_id }))),
    institutions,
    programmes,
    sources,
    admissions,
    quizQuestions,
    quizOptions,
  })
}
